def isNumber(s: str) -> bool:
    s = s.strip()
    if s.startswith(('+', '-')):
        s = s[1:]
    parts = s.split('e')
    if len(parts) > 2:
        return False
    for i, part in enumerate(parts):
        if i == 1 and part.startswith(('+', '-')):
            part = part[1:]
        if not part.replace('.', '', 1).isdigit():
            return False
    return True
